import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.RycU2wFZ.js";const p=JSON.parse('{"title":"Common Agent Failure Modes","description":"","frontmatter":{},"headers":[],"relativePath":"learn/01-agent-basics/agent-failure-modes.md","filePath":"learn/01-agent-basics/agent-failure-modes.md","lastUpdated":1792595354000}'),i={name:"learn/01-agent-basics/agent-failure-modes.md"};function r(s,e,c,l,d,u){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="common-agent-failure-modes" tabindex="-1">Common Agent Failure Modes <a class="header-anchor" href="#common-agent-failure-modes" aria-label="Permalink to &quot;Common Agent Failure Modes&quot;">​</a></h1><p>Agents combine probabilistic model output with tools that can affect external systems. Failures can arise from reasoning, input data, orchestration, integrations, or permissions.</p><h2 id="reasoning-errors" tabindex="-1">Reasoning errors <a class="header-anchor" href="#reasoning-errors" aria-label="Permalink to &quot;Reasoning errors&quot;">​</a></h2><p>A model may misunderstand a request, make an unsupported inference, overlook a constraint, or state uncertainty as fact. Early mistakes can compound through otherwise valid tool calls. Check sources, validate intermediate results, and make uncertainty visible.</p><h2 id="prompt-injection-and-untrusted-content" tabindex="-1">Prompt injection and untrusted content <a class="header-anchor" href="#prompt-injection-and-untrusted-content" aria-label="Permalink to &quot;Prompt injection and untrusted content&quot;">​</a></h2><p>Webpages, documents, and tool results may contain instructions that attempt to redirect the agent. Treat retrieved content as data, isolate it from trusted instructions, and never let model text modify its own permissions. Enforce sensitive actions in deterministic code.</p><h2 id="tool-and-integration-failures" tabindex="-1">Tool and integration failures <a class="header-anchor" href="#tool-and-integration-failures" aria-label="Permalink to &quot;Tool and integration failures&quot;">​</a></h2><p>Tools can return stale or malformed data, fail partially, or time out after completing an action. Validate schemas and business rules at integration boundaries. For writes and payments, reconcile uncertain results before retrying.</p><h2 id="loops-and-runaway-execution" tabindex="-1">Loops and runaway execution <a class="header-anchor" href="#loops-and-runaway-execution" aria-label="Permalink to &quot;Loops and runaway execution&quot;">​</a></h2><p>An agent may repeat calls because it fails to recognize completion or receives unexpected results. Limit steps, time, retries, concurrency, and resource use. Detect repeated calls and provide a stop path. For paid calls, enforce both per-call and cumulative budgets.</p><h2 id="excessive-permissions-and-unclear-identity" tabindex="-1">Excessive permissions and unclear identity <a class="header-anchor" href="#excessive-permissions-and-unclear-identity" aria-label="Permalink to &quot;Excessive permissions and unclear identity&quot;">​</a></h2><p>Broad credentials can turn a small model error into a serious incident. Bind identity to authenticated credentials, grant least privilege, and check each sensitive action against server-side policy rather than trusting model instructions.</p><h2 id="unclear-outcomes-and-accountability" tabindex="-1">Unclear outcomes and accountability <a class="header-anchor" href="#unclear-outcomes-and-accountability" aria-label="Permalink to &quot;Unclear outcomes and accountability&quot;">​</a></h2><p>A timeout does not prove an operation failed. Represent pending or unknown results explicitly and query the original operation before creating a duplicate. Keep an audit trail of relevant inputs and actions while protecting secrets and sensitive data.</p><p>Assume models, tools, networks, and orchestration can each fail. The more impact a tool can have, the narrower its permissions and the stronger its validation and recovery path should be.</p>',15)])])}const h=a(i,[["render",r]]);export{p as __pageData,h as default};
